        rank = new int[size];
        findCount = 0;
        unionCount = 0;
        initializeStructure();
    }

    @Override
    public int find(int i) {
        validateIndex(i);
        findCount++;
        if (parent[i] != i) {
            parent[i] = find(parent[i]);
        }
        return parent[i];
    }

    @Override
    public void union(int i, int j) {
        validateIndex(i);
        validateIndex(j);
        unionCount++;

        int irep = find(i);
        int jrep = find(j);

        if (irep == jrep) {
            return;
        }

        performUnion(irep, jrep);
    }

    @Override
    public boolean isConnected(int i, int j) {
        validateIndex(i);
        validateIndex(j);
        return find(i) == find(j);
    }

    @Override
